          "broader_review_uses"
        ],
        "value": {
          "material": "Associations between pathobiont abundance, decreased Ruminococcaceae, and dynamic changes in Bacteroides with irAE onset/remission."
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::ce5771d0255e802db4f70946"
